INSERT INTO `pages` VALUES (1,'Laman Kosong','kosong',NULL,'-',NULL,'published',NULL,NULL,NULL,5,'2026-01-14 11:27:59','2026-01-23 11:59:03'),(2,'Laman Kosong','laman-kosong',NULL,'-',NULL,'published',NULL,NULL,NULL,5,'2026-01-14 11:28:29','2026-01-23 11:59:03'),(4,'Tentang BPPU','tentang','profil','<h2>Tentang BPPU IKIP Siliwangi</h2><p>Badan Pengelola Pendapatan dan Usaha (BPPU) IKIP Siliwangi merupakan unit pengelola yang bertanggung jawab atas berbagai kegiatan usaha dan pendapatan di lingkungan kampus IKIP Siliwangi.</p><h3>Visi</h3><p>Menjadi unit pengelola yang profesional, transparan, dan akuntabel dalam mengelola usaha dan pendapatan kampus.</p><h3>Misi</h3><ul><li>Mengelola unit-unit usaha kampus dengan profesional</li><li>Meningkatkan pendapatan kampus melalui berbagai usaha</li><li>Memberikan pelayanan terbaik kepada civitas akademika</li><li>Menciptakan lapangan kerja bagi mahasiswa</li></ul>',NULL,'published',NULL,NULL,NULL,5,'2026-01-23 11:57:56','2026-01-23 11:57:56');
/*!40000 ALTER TABLE `pages` ENABLE KEYS */;
