INSERT INTO `roles` VALUES (1,'head','web','University leadership with executive dashboard access. Can view comprehensive reports, financial statements, and cash flow analytics. Read-only access for strategic oversight and decision-making.','2026-01-22 10:09:00','2026-01-22 10:09:00'),(2,'sysadmin','web','System administrator with full user management capabilities. Responsible for managing user accounts, assigning roles, and maintaining system security. Has comprehensive access to all cash books and system configurations.','2026-01-22 10:09:00','2026-01-22 10:09:00'),(3,'officer','web','Administrative officer responsible for daily operational tasks. Manages content, financial entries, reports, and unit-specific operations. Full access to create, edit, and manage operational data.','2026-01-22 10:09:00','2026-01-22 10:09:00'),(4,'canteen','web','Canteen staff member with access to order management and inventory tracking. Can view incoming orders, manage stock levels, and monitor canteen-specific transactions.','2026-01-22 10:09:00','2026-01-22 10:09:00'),(5,'shop','web','Shop staff member with access to retail operations. Can manage stock opname, view incoming orders, track inventory levels, and handle shop-specific transactions.','2026-01-22 10:09:00','2026-01-22 10:09:00'),(6,'buyer','web','Canteen member (pembeli) with ordering access and points collection. Can place orders at canteen and accumulate loyalty points for discounts on future purchases.','2026-02-01 23:26:51','2026-02-01 23:26:51'),(7,'mitra','web','Business partner (supplier, tenant, vendor) with access to manage their own products, view orders, and track transactions. Can update inventory and manage business relationship with the institution.','2026-02-04 10:20:30','2026-02-04 10:20:30'),(8,'supplier','web','Supplier partner providing goods and products to the institution.','2026-02-04 10:25:57','2026-02-04 10:25:57'),(9,'tenant','web','Tenant partner managing booth or space within the institution premises.','2026-02-04 10:25:57','2026-02-04 10:25:57'),(10,'vendor','web','Vendor partner providing specific services or products.','2026-02-04 10:25:57','2026-02-04 10:25:57'),(11,'distributor','web','Distributor partner for product distribution and supply chain.','2026-02-04 10:25:57','2026-02-04 10:25:57'),(12,'produsen','web','Manufacturer/producer partner creating and supplying products.','2026-02-04 10:25:57','2026-02-04 10:25:57'),(13,'reseller','web','Reseller partner for product resale activities.','2026-02-04 10:25:57','2026-02-04 10:25:57'),(14,'konsinyasi','web','Consignment partner managing goods on consignment basis.','2026-02-04 10:25:57','2026-02-04 10:25:57');
/*!40000 ALTER TABLE `roles` ENABLE KEYS */;
UNLOCK TABLES;

