INSERT INTO `shop_items` VALUES (1,'Mug IKIP Siliwangi','Mug keramik berkualitas tinggi dengan logo IKIP Siliwangi. Cocok untuk minum kopi atau teh favorit Anda. Kapasitas 350ml dengan desain elegant.','Souvenir',45000.00,'https://placehold.co/400x300/996600/FFFFFF/png?text=Mug+IKIP+Siliwangi',25,1,1,'2026-01-23 10:51:08','2026-01-23 10:51:08'),(2,'Pin IKIP Siliwangi','Pin enamel premium dengan logo IKIP Siliwangi. Material berkualitas dengan finishing glossy. Cocok untuk dikoleksi atau sebagai hadiah.','Souvenir',15000.00,'https://placehold.co/400x300/996600/FFFFFF/png?text=Pin+IKIP+Siliwangi',50,1,2,'2026-01-23 10:51:09','2026-01-23 10:51:09'),(3,'Tas Belanja IKIP Siliwangi','Tas belanja dari bahan kanvas tebal dan kuat dengan logo IKIP Siliwangi. Ramah lingkungan dan dapat digunakan berulang kali. Ukuran 40x35cm.','Souvenir',35000.00,'https://placehold.co/400x300/996600/FFFFFF/png?text=Tas+Belanja+IKIP',30,1,3,'2026-01-23 10:51:09','2026-01-23 10:51:09');
