  `tanggal` date NOT NULL,
  `kategori` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `jenis_transaksi` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Jenis transaksi: Tunai, Transfer, QRIS, dll',
  `unit_kerja_id` bigint unsigned DEFAULT NULL,
  `deskripsi` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `pemasukan` decimal(15,2) NOT NULL DEFAULT '0.00',
  `pengeluaran` decimal(15,2) NOT NULL DEFAULT '0.00',
  `bukti_transaksi` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
