  `bukti_aktivitas_link` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `transaksi_kas_transaction_id_unique` (`transaction_id`),
  KEY `transaksi_kas_buku_kas_id_foreign` (`buku_kas_id`),
  KEY `transaksi_kas_unit_kerja_id_foreign` (`unit_kerja_id`),
  CONSTRAINT `transaksi_kas_buku_kas_id_foreign` FOREIGN KEY (`buku_kas_id`) REFERENCES `buku_kas` (`id`) ON DELETE CASCADE,
  CONSTRAINT `transaksi_kas_unit_kerja_id_foreign` FOREIGN KEY (`unit_kerja_id`) REFERENCES `work_units` (`id`) ON DELETE SET NULL
